const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    var nm = ee.FeatureCollection('TIGER/2018/States')
      .filter(ee.Filter.eq('NAME', 'New Mexico'))
      .geometry();
    var startYear = 1995;
    var endYear = 2024; // 30 years inclusive [1995..2024]
    var scale = 3000;
    var eps = 1e-3;

    // 2. Utilities: Masking, LST scaling, and July collections
    function maskL2(img) {
      var qa = img.select('QA_PIXEL');
      var mask = qa.bitwiseAnd(1 << 3).eq(0) // cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0))    // cloud shadow
        .and(qa.bitwiseAnd(1 << 5).eq(0))    // snow
        .and(qa.bitwiseAnd(1 << 7).eq(0));   // water
      return img.updateMask(mask);
    }
    function addLST(img) {
      var band = ee.String(ee.Algorithms.If(img.bandNames().contains('ST_B10'), 'ST_B10', 'ST_B6'));
      var lstK = img.select(band).multiply(0.00341802).add(149.0).rename('LST');
      return lstK.copyProperties(img, img.propertyNames());
    }
    function julyCollection(year, widen) {
      var start = ee.Date.fromYMD(year, 7, 1);
      var end = ee.Date.fromYMD(year, 8, 1);
      if (widen) {
        start = ee.Date.fromYMD(year, 6, 15);
        end = ee.Date.fromYMD(year, 8, 15);
      }
      var l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterDate(start, end).filterBounds(nm).map(maskL2).map(addLST);
      var l7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
        .filterDate(start, end).filterBounds(nm).map(maskL2).map(addLST);
      var l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterDate(start, end).filterBounds(nm).map(maskL2).map(addLST);
      var l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterDate(start, end).filterBounds(nm).map(maskL2).map(addLST);
      return l5.merge(l7).merge(l8).merge(l9).select('LST');
    }

    // Early check for 2016 availability with possible recovery
    var col2016 = julyCollection(2016, false);
    var n2016 = await col2016.size().getInfo();
    if (n2016 === 0) {
      // Try widen window
      col2016 = julyCollection(2016, true);
      n2016 = await col2016.size().getInfo();
      if (n2016 === 0) {
        console.log('2016 July Images: 0');
        console.log('C1');
        return;
      }
    }

    // 3. Compute per-year stats server-side
    var years = ee.List.sequence(startYear, endYear);
    var statsList = years.map(function(y) {
      y = ee.Number(y);
      var col = julyCollection(y, false);
      var n = col.size();
      // If empty, mark empties (we will not attempt widen here to keep consistent processing)
      var composite = ee.Image(ee.Algorithms.If(n.gt(0), col.median(), ee.Image(0).updateMask(ee.Image(0))));
      composite = composite.clip(nm);
      var meanDict = composite.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: nm,
        scale: scale,
        maxPixels: 1e9
      });
      var meanK = ee.Number(meanDict.get('LST'));
      var validCount = ee.Number(composite.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: nm,
        scale: scale,
        maxPixels: 1e9
      }).get('LST'));
      var totCount = ee.Number(ee.Image.constant(1).rename('LST').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: nm,
        scale: scale,
        maxPixels: 1e9
      }).get('LST'));
      var coverage = validCount.divide(totCount).multiply(100);
      return ee.Dictionary({
        year: y,
        nImages: n,
        meanK: meanK,
        meanC: ee.Algorithms.If(meanK, meanK.subtract(273.15), null),
        validCount: validCount,
        totCount: totCount,
        coveragePct: coverage
      });
    });
    var stats = await statsList.getInfo();

    // 4. Extract 2016 stats and validate
    var s2016 = stats.find(function(d){ return d.year === 2016; });
    var meanK2016 = s2016 && s2016.meanK;
    var vCnt2016 = s2016 && s2016.validCount;
    var tCnt2016 = s2016 && s2016.totCount;

    if (meanK2016 === null || meanK2016 === undefined) {
      // Images in collection but post-masking no valid pixels
      if (n2016 > 0 && (vCnt2016 === 0 || vCnt2016 === null)) {
        console.log(`2016 July Images: ${n2016} (Valid px: 0)`);
        console.log('C2');
        return;
      } else {
        console.log('C3');
        return;
      }
    }
    if (meanK2016 < 200 || meanK2016 > 400) {
      console.log(`2016 July Mean LST (K) out of plausible range: ${meanK2016}`);
      console.log('C3');
      return;
    }

    // 5. Determine max of other years
    var others = stats.filter(function(d){ return d.year !== 2016; });
    var othersValid = others.filter(function(d){ return d.meanK !== null && d.meanK !== undefined; });
    if (othersValid.length === 0) {
      console.log('No valid comparison years.');
      console.log('C3');
      return;
    }
    var maxOther = othersValid.reduce(function(acc, d){ return (d.meanK > acc.meanK) ? d : acc; }, othersValid[0]);

    // 6. Print concise evidence (<=20 lines)
    console.log(`Years analyzed: ${startYear}-${endYear} (N=${endYear - startYear + 1})`);
    var cov2016 = (vCnt2016 && tCnt2016) ? (100.0 * vCnt2016 / tCnt2016) : null;
    var meanC2016 = meanK2016 - 273.15;
    console.log(`2016 July: images ${n2016}, mean LST ${meanK2016.toFixed(2)} K (${meanC2016.toFixed(2)} °C), valid px ${vCnt2016}/${tCnt2016} (${cov2016 ? cov2016.toFixed(1) : 'NA'}%)`);
    var moC = maxOther.meanK - 273.15;
    console.log(`Max July (others): ${maxOther.year} | images ${maxOther.nImages}, mean LST ${maxOther.meanK.toFixed(2)} K (${moC.toFixed(2)} °C), valid px ${maxOther.validCount}/${maxOther.totCount} (${(maxOther.coveragePct||0).toFixed(1)}%)`);

    // 7. Final decision
    var isHigher = (meanK2016 > (maxOther.meanK + eps));
    console.log(isHigher ? 'A' : 'B');
  } catch (e) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
